-- ============================================================
-- WMS tables for Oracle Skyline (schema FECITALIA)
-- Mirrors the Informix wms_* tables 1:1 (same table/column names)
-- so backend.py keeps the same SQL and JSON field names.
--
-- Differences vs Informix:
--   * SERIAL                -> NUMBER GENERATED BY DEFAULT AS IDENTITY
--     (BY DEFAULT so the migration script can copy the original ids;
--      it re-syncs the identities afterwards)
--   * BOOLEAN ('t'/'f')     -> NUMBER(1) (1/0)
--   * DATETIME YEAR TO SEC  -> DATE (Oracle DATE carries the time)
--   * LVARCHAR(1000)        -> VARCHAR2(1000)
--   * wms_log."timestamp"/"user" are reserved in Oracle, renamed to
--     log_ts / log_user; backend.py aliases them back in the SELECT.
--
-- Run once as FECITALIA (e.g. SQL*Plus / SQL Developer).
-- ============================================================

CREATE TABLE wms_items (
    id_pacco    NUMBER(10) GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    id_art      VARCHAR2(20),
    id_mov      VARCHAR2(30),   -- ADAPTA movement ('83005') or Skyline document ('2026/CA/38')
    fornitore   VARCHAR2(12),
    area        VARCHAR2(2),
    scaffale    VARCHAR2(2),
    colonna     VARCHAR2(3),
    piano       VARCHAR2(2),
    qta         NUMBER(10),
    dimensione  VARCHAR2(18),
    id          NUMBER(10)
);
CREATE INDEX wms_items_loc_ix ON wms_items (area, scaffale, colonna, piano);
CREATE INDEX wms_items_art_ix ON wms_items (id_art);

CREATE TABLE wms_scaffali (
    area                VARCHAR2(2)  NOT NULL,
    scaffale            VARCHAR2(2)  NOT NULL,
    colonna             VARCHAR2(3)  NOT NULL,
    piano               VARCHAR2(2)  NOT NULL,
    fornitore_preferito VARCHAR2(12),
    volume_libero       NUMBER(10),
    CONSTRAINT wms_scaffali_pk PRIMARY KEY (area, scaffale, colonna, piano)
);

CREATE TABLE wms_volume (
    dimensione  VARCHAR2(10) PRIMARY KEY,
    volume      NUMBER(10)
);

CREATE TABLE wms_prelievi (
    id          NUMBER(10) GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    odl         VARCHAR2(30),
    id_art      VARCHAR2(30),
    area        VARCHAR2(2),
    scaffale    VARCHAR2(2),
    colonna     VARCHAR2(3),
    piano       VARCHAR2(2),
    qta         NUMBER(10)
);
CREATE INDEX wms_prelievi_odl_ix ON wms_prelievi (odl);

CREATE TABLE wms_log (
    id                   NUMBER(10) GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    log_ts               DATE,
    operation_type       VARCHAR2(50),
    operation_details    VARCHAR2(255),
    log_user             VARCHAR2(50),
    ip_address           VARCHAR2(50),
    article_code         VARCHAR2(50),
    source_location      VARCHAR2(100),
    destination_location VARCHAR2(100),
    quantity             NUMBER(10),
    is_undone            NUMBER(1) DEFAULT 0,
    can_undo             NUMBER(1) DEFAULT 1,
    additional_data      VARCHAR2(1000)
);
CREATE INDEX wms_log_ts_ix ON wms_log (log_ts);

-- ---------- Ispezioni scaffali (v2) ----------

CREATE TABLE wms_inspection_cycles (
    id          NUMBER(10) GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    cycle_name  VARCHAR2(100) NOT NULL,
    start_date  DATE NOT NULL,
    end_date    DATE,
    created_at  DATE DEFAULT SYSDATE,
    is_active   NUMBER(5) DEFAULT 1,
    notes       VARCHAR2(255),
    CONSTRAINT wms_insp_cycles_start_uk UNIQUE (start_date)
);

CREATE TABLE wms_inspection_questions (
    id              NUMBER(10) GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    question_text   VARCHAR2(255) NOT NULL,
    question_order  NUMBER(10) NOT NULL,
    is_active       NUMBER(5) DEFAULT 1,
    created_at      DATE DEFAULT SYSDATE
);

CREATE TABLE wms_shelf_inspections (
    id              NUMBER(10) GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    cycle_id        NUMBER(10) NOT NULL,
    shelf_id        VARCHAR2(50) NOT NULL,
    inspection_date DATE NOT NULL,
    status          VARCHAR2(20),
    inspector_name  VARCHAR2(100),
    created_at      DATE DEFAULT SYSDATE,
    updated_at      DATE DEFAULT SYSDATE,
    notes           VARCHAR2(255),
    CONSTRAINT wms_shelf_insp_uk UNIQUE (cycle_id, shelf_id)
);
CREATE INDEX wms_shelf_insp_cycle_ix ON wms_shelf_inspections (cycle_id);

CREATE TABLE wms_inspection_responses (
    id              NUMBER(10) GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    inspection_id   NUMBER(10) NOT NULL,
    question_id     NUMBER(10) NOT NULL,
    question_text   VARCHAR2(255),
    answer          VARCHAR2(10),
    notes           VARCHAR2(255),
    created_at      DATE DEFAULT SYSDATE,
    CONSTRAINT wms_insp_resp_uk UNIQUE (inspection_id, question_id)
);
CREATE INDEX wms_insp_resp_q_ix ON wms_inspection_responses (question_id);

-- Legacy v1 inspections (still referenced by the /api/shelf-inspection* v1 routes)
CREATE TABLE wms_inspections (
    id              NUMBER(10) GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    shelf_id        VARCHAR2(20),
    inspection_date DATE,
    status          VARCHAR2(20),
    is_current      NUMBER(10),
    CONSTRAINT wms_inspections_uk UNIQUE (shelf_id, inspection_date)
);
